/* wordfreq.cpp - counts word frequencies with a hand‑rolled chained hash table.
 * Prints words with count >= MIN (arg, default 2) in first‑seen order, then totals.
 * Trap: output order is first‑seen order (not sorted, not hash order); words are
 * lower‑cased and split on non‑alphabetic characters.
 */
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <cctype>
#include <vector>
#include <string>

#define NBUCKET 101

struct entry {
    std::string word;
    int count;
    int order;
    entry *next;
};

static entry *table[NBUCKET];
static std::vector<entry *> seen;
static int nseen = 0;

static unsigned int hash(const char *s)
{
    unsigned int h = 0;
    while (*s) h = h * 33 + static_cast<unsigned char>(*s++);
    return h % NBUCKET;
}

static void add(const char *w)
{
    unsigned int h = hash(w);
    entry *e;
    for (e = table[h]; e; e = e->next)
        if (strcmp(e->word.c_str(), w) == 0) { e->count++; return; }
    if (nseen >= 4096) return;
